FECHA = ('2 de noviembre', 'November 2')
TITULO = ('Más daño para todos y árboles rehechos', 'More damage for everyone and reworked talent trees')
RESUMEN = ('Último parche antes del lanzamiento: todas las clases pegan más y los enemigos de nivel alto tienen más vida. Se rehacen muchos talentos '
           '(paladín, pícaro, druida Feral y Restauración), el pícaro estrena Shank y Death Mark, el chamán pierde Lava Burst y el mago Frost Blast. '
           'Entrenar del 1 al 60 cuesta unos 206 de oro y las bolsas ya no se equipan solas.',
           'The last patch before launch: every class hits harder and higher-level creatures have more health. Many talents are reworked '
           '(Paladin, Rogue, Feral and Restoration Druid), Rogues get Shank and Death Mark, Shamans lose Lava Burst and Mages lose Frost Blast. '
           'Training from 1 to 60 costs about 206 gold and bags no longer equip themselves.')


def parche():
    """Entrada en el formato de cambios_beta.PARCHES (solo castellano)."""
    return (FECHA[0], TITULO[0], RESUMEN[0], [(s, es) for s, es, _ in GENERAL], {k[0]: [(s, es) for s, es, _ in v] for k, v in CLASES.items()})


def ingles():
    """{texto castellano: texto inglés} de todo lo de este parche, para las claves de traducción."""
    d = {FECHA[0]: FECHA[1], FECHA[0].upper(): FECHA[1].upper(), TITULO[0]: TITULO[1], RESUMEN[0]: RESUMEN[1]}
    for s, es, en in GENERAL + [x for v in CLASES.values() for x in v]:
        d[es] = en
    for k in CLASES:
        d[k[0]] = k[1]
    return d
